            w.WriteStartObject();
            w.WriteStartArray("programas");
            foreach (var (programa, con) in salida)
            {
                w.WriteStartObject();
                w.WriteString("programaId", programa);
                w.WriteStartArray("estudiantes");
                foreach (var (est, perdidas) in con)
