                    w.WriteEndArray();
                    w.WriteEndObject();
                }

                w.WriteEndArray();
                w.WriteEndObject();
            }

            w.WriteEndArray();
            w.WriteEndObject();
        });
    }

    /// <summary>La herramienta de asistencia solo lee asistencia; el nombre de la asignatura viene en esa misma fila.</summary>
